To replicate:

```python
import torch.autograd.forward_ad as fwAD
import torch

class Test(torch.autograd.Function):
    @staticmethod
    def forward(ctx, nt, x):
        return x.clone()

    @staticmethod
    def jvp(ctx, _, x_t):
        return x_t

x = torch.tensor(1.)
t = torch.tensor(1.)

with fwAD.dual_level():
    dual_x = fwAD.make_dual(x, t)
    Test.apply(1, dual_x)
```

