cc @ezyang @gchanan @kadeng @albanD @gqchen @pearu @nikitaved @soulitzer @Lezcano @Varal7 @bdhirsh @Chillee @samdow @kshitij12345 @janeyx99

If custom autograd function returns input, then subclass is stripped from the output:
```python
import torch

class Custom(torch.Tensor):
    def __init__(self, data):
        super().__init__()
        self._data = data

    @classmethod
    def __torch_function__(cls, func, types, args=(), kwargs={}):
        if kwargs is None:
            kwargs = {}
        args = tuple(a._data if isinstance(a, cls) else a for a in args)
        out = func(*args, **kwargs)
        if isinstance(out, torch.Tensor):
            out = cls(out)
        return out

    def __repr__(self):
        return f"Custom({self._data})"


class Fn(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input):
        print(input)
        return input

    @staticmethod
    def backward(ctx):
        pass


x = Custom(torch.randn(2, 3))
y = Fn.apply(x)
print(y)
prints
Custom(tensor([[-0.2426,  1.2528, -0.1921],
        [ 0.5356,  0.4451,  1.2015]]))
tensor([[-0.2426,  1.2528, -0.1921],
        [ 0.5356,  0.4451,  1.2015]])
```
That's because in `custom_function.cpp` `view_as` is called, and of course it never goes through `__torch_function__` . There are of course workarounds to never return input and explicitly return an alias, but is there a way to avoid this footgun?

cc @ezyang @gchanan @zou3519 @kadeng @albanD @gqchen @pearu @nikitaved @soulitzer @Lezcano @Varal7

```
import torch

class MulY(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x, ys):
        ctx.save_for_backward(ys[0])
        return x * ys[0]

    @staticmethod
    def backward(ctx, grad_out):
        ys, = ctx.saved_tensors 
        return grad_out * ys

@torch.compile(backend="eager", fullgraph=True)
def f(x, ys):
    return MulY.apply(x, ys)

x = torch.tensor(2., requires_grad=True)
ys = [torch.tensor(2.)]
expected = MulY.apply(x, ys)
out = f(x, ys)
assert torch.allclose(out, expected)
```

We should be able to support this with fullgraph=True
We should be able to do something like manually_set_inputs=False for autograd.Function HOP tracing.

